"""The ``foley`` command-line interface (``argparse``, the verbs generated by ``cw``).

Two kinds of command share one parser:

* **the verbs** (#62): every verb of :data:`foley.agent.mcp.VERBS`, the table MCP serves
  too, generated by ``cw`` from its signature and docstring, so a verb added there is a
  command here with no CLI code. Its result is printed as JSON; a dict argument (a
  timeline) is given as JSON; a result with ``"ok": false`` exits 1::

      foley find "The door creaked open in the storm." --territory US
      foley score "Rain on the roof." --no-commercial-ok
      foley generate "a glass shatters" --backend elevenlabs
      foley set-master '{"items": []}' --target-lufs -16

* **the commands written here**, for what is not a verb (bulk corpora, folders, the
  agent kit, the evaluation harness)::

      foley demo                       # offline ingest->search over the bundled fixture
      foley bootstrap [--rings 0,1] [--corpora fsd50k,foleyset] [--data-dir DIR]
                      [--accept-ai-restricted] [--no-commercial-filter]
      foley ingest PATH [--license ID] [--min-status warn|pass|fail] [--no-qc]
      foley search QUERY [-k N] [--commercial-ok]

Wired as the ``foley`` console entry point (``[project.scripts]``). Every command is a
thin call into the library facade; the CLI only parses args and prints.
"""

from __future__ import annotations

import argparse
import json
import sys
import typing
from typing import Optional


def _int_csv(value: str) -> "tuple[int, ...]":
    """Parse ``"0,1"`` -> ``(0, 1)``."""
    return tuple(int(x) for x in value.split(",") if x.strip() != "")


def _str_csv(value: str) -> "list[str]":
    """Parse ``"fsd50k,foleyset"`` -> ``["fsd50k", "foleyset"]``."""
    return [x.strip() for x in value.split(",") if x.strip() != ""]


def _cmd_demo(args) -> int:
    from . import demo

    result = demo(query=args.query, k=args.k)
    print(json.dumps(result, indent=2, default=str))
    return 0


def _cmd_bootstrap(args) -> int:
    from . import bootstrap
    from .sources.base import CORPUS_REGISTRY

    corpora = _str_csv(args.corpora) if args.corpora else None
    rings = _int_csv(args.rings) if args.rings else (0, 1)

    if args.accept_ai_restricted:
        restricted = sorted(
            n
            for n, a in CORPUS_REGISTRY.items()
            if a.ring == 2 and (corpora is None or n in corpora)
        )
        print(
            "CONSENT: --accept-ai-restricted admits AI-training-restricted corpora "
            f"({', '.join(restricted) or 'none selected'}); their licenses forbid "
            "using the audio to train models. Proceeding with recorded consent.",
            file=sys.stderr,
        )

    commercial_only = False if args.no_commercial_filter else None
    reports = bootstrap(
        rings=rings,
        corpora=corpora,
        data_dir=args.data_dir,
        accept_ai_restricted=args.accept_ai_restricted,
        commercial_only=commercial_only,
    )
    for name, report in reports.items():
        print(f"{name}: {json.dumps(report.summary())}")
    return 0


def _cmd_ingest(args) -> int:
    from . import ingest
    from .qc import QCStatus

    report = ingest(
        args.path,
        license=args.license,  # None => rights unknown (#55); an id is validated upstream
        qc=not args.no_qc,  # the facade maps qc -> ingest_one's do_qc
        min_status=QCStatus(args.min_status),
    )
    print(json.dumps(report.summary(), indent=2))
    return 0


def _assertable_license_ids() -> "list[str]":
    """Licence ids a user may assert on ingest (every LICENSE_FLAGS row but 'unknown')."""
    from .index.ingest import ASSERTABLE_LICENSE_IDS

    return sorted(ASSERTABLE_LICENSE_IDS)


def _cmd_restamp(args) -> int:
    from .index.ingest import restamp_rights

    changed = restamp_rights(
        license=args.license,
        ids=args.ids or None,
        select=args.select,
        apply=args.apply,
    )
    verb = "re-stamped" if args.apply else "would re-stamp (dry run; pass --apply)"
    print(f"{verb} {len(changed)} sound(s) as {args.license}")
    for sid in changed:
        print(f"  {sid}")
    return 0


def _cmd_eval(args) -> int:
    from . import evaluate
    from .eval.baseline import (
        DEFAULT_BASELINE_PATH,
        load_baseline,
        write_baseline,
    )
    from .eval.golden import (
        DEFAULT_GOLDEN_PATH,
        RING0_CORPUS_PATH,
        load_golden,
    )

    report = evaluate(k=args.k, golden=args.golden)
    metric = "ndcg@10"
    print(f"mean {metric}: {report.mean[metric]:.4f}")
    for qid, m in sorted(report.per_query.items()):
        print(f"  {qid}: {m[metric]:.4f}  (rank={report.ranks.get(qid, '-')})")

    if args.update_baseline:
        import datetime

        try:  # preserve the current golden-set revision label across re-baselines
            revision = load_baseline(DEFAULT_BASELINE_PATH)["golden"]["revision"]
        except (FileNotFoundError, KeyError):
            revision = "gld-v1"
        bl = write_baseline(
            report,
            path=DEFAULT_BASELINE_PATH,
            seed_path=args.golden or DEFAULT_GOLDEN_PATH,
            manifest_path=RING0_CORPUS_PATH,
            updated_at=datetime.date.today().isoformat(),
            n_items=len(load_golden(args.golden or DEFAULT_GOLDEN_PATH)),
            revision=revision,
        )
        print(f"baseline updated -> {DEFAULT_BASELINE_PATH} (value={bl['value']})")
        return 0

    baseline = load_baseline()
    delta = report.mean[metric] - baseline["value"]
    floor = baseline["value"] - baseline["tolerance"]
    status = "PASS" if report.mean[metric] >= floor else "FAIL"
    print(
        f"baseline={baseline['value']:.4f} floor={floor:.4f} Δ={delta:+.4f} -> {status}"
    )
    return 0 if report.mean[metric] >= floor else 1


def _cmd_eval_fit(args) -> int:
    from . import evaluate_fit

    report = evaluate_fit(
        k=args.k,
        golden=args.golden,
        sample=args.sample,
        level=args.level,
        seed=args.seed,
        llm=args.llm,
    )
    if args.update_baseline or args.baseline:
        return _fit_baseline_command(args, report)
    if args.json:
        import dataclasses
        import json

        print(json.dumps(dataclasses.asdict(report), indent=2))
        return 0 if report.gate(args.min_fit_precision) else 1
    print(
        f"fit_precision={report.fit_precision:.4f} recall={report.fit_recall:.4f} "
        f"f1={report.fit_f1:.4f} fit_score={report.fit_score:.4f} "
        f"auto_accept={report.auto_accept_rate:.4f}"
    )
    print(
        f"judge={report.judge_model} accepted={report.n_accepted} confirmed={report.n_confirmed}"
    )
    for stratum, s in sorted(report.strata.items()):
        print(f"  {stratum}: fit_precision={s['fit_precision']:.4f} (n={s['n']})")
    # Report-only unless a floor is supplied (Tier-2 is nightly/pre-release, not a PR gate).
    if args.min_fit_precision is not None:
        ok = report.gate(args.min_fit_precision)
        print(f"floor={args.min_fit_precision:.4f} -> {'PASS' if ok else 'FAIL'}")
        return 0 if ok else 1
    return 0


def _fit_baseline_command(args, report) -> int:
    """``eval-fit --update-baseline`` (re-stamp) or ``--baseline`` (gate against the stamp)."""
    from .eval.baseline import (
        DEFAULT_FIT_BASELINE_PATH,
        check_fit_baseline,
        load_baseline,
        write_fit_baseline,
    )
    from .eval.golden import DEFAULT_GOLDEN_PATH, RING0_CORPUS_PATH, load_golden

    seed_path = args.golden or DEFAULT_GOLDEN_PATH
    if args.update_baseline:
        import datetime

        try:  # keep the golden-set revision label across re-stamps
            revision = load_baseline(DEFAULT_FIT_BASELINE_PATH)["golden"]["revision"]
        except (FileNotFoundError, KeyError):  # else the retrieval baseline's label
            revision = load_baseline()["golden"]["revision"]
        bl = write_fit_baseline(
            report,
            path=DEFAULT_FIT_BASELINE_PATH,
            level=args.level,
            sample=args.sample,
            seed_path=seed_path,
            manifest_path=RING0_CORPUS_PATH,
            updated_at=datetime.date.today().isoformat(),
            n_items=len(load_golden(seed_path)),
            revision=revision,
        )
        print(
            f"fit baseline updated -> {DEFAULT_FIT_BASELINE_PATH} (value={bl['value']})"
        )
        return 0
    baseline = load_baseline(DEFAULT_FIT_BASELINE_PATH)
    ok, message = check_fit_baseline(
        report,
        baseline,
        level=args.level,
        sample=args.sample,
        seed_path=seed_path,
        manifest_path=RING0_CORPUS_PATH,
    )
    print(f"{message} -> {'PASS' if ok else 'FAIL'}")
    return 0 if ok else 1


def _cmd_search(args) -> int:
    from . import search

    hits = search(args.query, k=args.k, commercial_ok=not args.include_noncommercial)
    for hit in hits:
        rec = hit.sound
        print(
            f"{rec.id[:12]}  {rec.caption or '(no caption)'}  [{rec.license.license_id}]"
        )
    if not hits:
        print("(no hits)")
    return 0


def _optional_of(hint):
    """``Optional[X]`` -> ``X``; anything else unchanged (``list[dict]`` stays a list)."""
    args = typing.get_args(hint)
    if type(None) in args:
        rest = [a for a in args if a is not type(None)]
        if len(rest) == 1:
            return rest[0]
    return hint


def _true_or_false(token: str) -> bool:
    """A required bool on the command line: ``true`` / ``false`` (any case), nothing else."""
    words = {"true": True, "false": False}
    try:
        return words[token.strip().lower()]
    except KeyError:
        raise argparse.ArgumentTypeError(
            f"expected true or false, got {token!r}"
        ) from None


def _verb_decode(param, hint):
    """How a verb's parameter is read from the command line (``cw``'s decode seam).

    A ``dict`` (a timeline) is JSON, shown as ``NAME_JSON``; a ``bool`` with a default is
    ``--x`` / ``--no-x`` (so ``commercial_ok=True`` can be turned off), a required one
    ``true`` / ``false``; anything else as ``cw.MODERN`` reads it.
    """
    import inspect

    from cw.grammar import modern_decode

    bare = _optional_of(hint)
    if bare is dict or typing.get_origin(bare) is dict:
        return {"type": json.loads, "metavar": f"{param.name.upper()}_JSON"}
    if bare is bool:
        if param.default is inspect.Parameter.empty:
            return {"type": _true_or_false, "metavar": "{true,false}"}
        return {"action": argparse.BooleanOptionalAction}
    return modern_decode(param, hint)


def _verb_egress(result, *, out=None, err=None) -> int:
    """Print a verb's result as JSON; exit 1 when it says ``"ok": false``."""
    import cw

    cw.json_egress(result, out=out, err=err)
    refused = isinstance(result, dict) and result.get("ok") is False
    rows = isinstance(result, list) and any(
        isinstance(r, dict) and r.get("ok") is False for r in result
    )
    return 1 if refused or rows else 0


def _verb_convention():
    """``cw.MODERN`` but for the naming (a parameter with a default is an option, as
    argh had it) and short flags (none: the surface is generated, so ``-k`` would
    change meaning whenever a verb gains a parameter starting with ``k``)."""
    import dataclasses

    import cw

    return dataclasses.replace(
        cw.MODERN,
        naming=cw.ARGH.naming,
        short_flags=False,
        decode=_verb_decode,
        egress=_verb_egress,
    )


#: Parameter names a verb may not take on the CLI: the parser's own namespace keys
#: (``command`` its subcommand, ``func`` a written command's handler, ``_cw`` cw's).
RESERVED_VERB_PARAMS = frozenset({"command", "func", "_cw"})


def add_verbs(parser: argparse.ArgumentParser, verbs=None) -> argparse.ArgumentParser:
    """Add the CLI-enabled verbs of ``verbs`` (default: :data:`foley.agent.mcp.VERBS`)
    to ``parser``'s subcommands, one command each (#62).

    Raises:
        ValueError: If a verb's command clashes with a written one, or it takes a
            parameter named in :data:`RESERVED_VERB_PARAMS`.
    """
    import inspect

    import cw

    if verbs is None:
        from .agent.mcp import VERBS as verbs
    commands = {v.command: v.fn for v in verbs if v.cli}
    reserved = sorted(
        f"{name}({p})"
        for name, fn in commands.items()
        for p in inspect.signature(fn).parameters
        if p in RESERVED_VERB_PARAMS
    )
    if reserved:
        raise ValueError(f"verb parameter name(s) reserved by the CLI: {reserved}")
    taken = {
        name
        for action in parser._actions
        if isinstance(action, argparse._SubParsersAction)
        for name in action.choices
    }
    clash = sorted(taken & set(commands))
    if clash:  # one message for every Python (3.10's argparse lets the later one win)
        raise ValueError(
            f"verb command(s) {clash} clash with commands written in foley.cli: set "
            "cli=False on the verb (and say why), or rename one"
        )
    return cw.add_commands(parser, commands, convention=_verb_convention())


def build_parser() -> argparse.ArgumentParser:
    """Build the ``foley`` argument parser: the commands written here, then the verbs."""
    parser = argparse.ArgumentParser(
        prog="foley", description="foley — sound-effects retrieval facade"
    )
    sub = parser.add_subparsers(dest="command", required=True)

    p_demo = sub.add_parser(
        "demo", help="offline ingest->search over the bundled fixture"
    )
    p_demo.add_argument("--query", default="rain on a window")
    p_demo.add_argument("-k", type=int, default=3)
    p_demo.set_defaults(func=_cmd_demo)

    p_boot = sub.add_parser("bootstrap", help="seed the library from bulk corpora")
    p_boot.add_argument("--rings", help="comma-separated rings (default 0,1)")
    p_boot.add_argument(
        "--corpora", help="comma-separated corpus names (overrides --rings)"
    )
    p_boot.add_argument(
        "--data-dir", help="root holding downloaded corpora (data_dir/<name>)"
    )
    p_boot.add_argument(
        "--accept-ai-restricted",
        action="store_true",
        help="consent to admit Ring-2 AI-training-restricted corpora (Sonniss, BBC RemArc)",
    )
    p_boot.add_argument(
        "--no-commercial-filter",
        action="store_true",
        help="do not drop non-commercial clips (personal-use ingest)",
    )
    p_boot.set_defaults(func=_cmd_bootstrap)

    p_ing = sub.add_parser("ingest", help="ingest a local folder or file")
    p_ing.add_argument("path")
    p_ing.add_argument(
        "--license",
        choices=_assertable_license_ids(),
        metavar="LICENSE_ID",
        help="licence you assert for these files, e.g. user-owned for your own recordings "
        "(default: none — rights unknown, so foley.keep() refuses them for every use)",
    )
    p_ing.add_argument("--min-status", default="warn", choices=["fail", "warn", "pass"])
    p_ing.add_argument("--no-qc", action="store_true")
    p_ing.set_defaults(func=_cmd_ingest)

    p_rs = sub.add_parser(
        "restamp-rights",
        help="re-stamp stored sounds' licence (default: the ones an older foley "
        "marked user-owned without being told)",
    )
    p_rs.add_argument(
        "--license",
        default="unknown",
        choices=["unknown", "from-url", *_assertable_license_ids()],
        metavar="LICENSE_ID",
        help="licence to stamp (default: unknown = fail closed); from-url re-derives "
        "each record from the licence string its source served",
    )
    p_rs.add_argument(
        "--select",
        default="legacy-user-owned",
        choices=["legacy-user-owned", "legacy-elevenlabs", "has-license-url"],
        help="which stored sounds to re-stamp (default: legacy-user-owned)",
    )
    p_rs.add_argument("--ids", nargs="*", help="re-stamp exactly these sound ids")
    p_rs.add_argument("--apply", action="store_true", help="write (default: dry run)")
    p_rs.set_defaults(func=_cmd_restamp)

    p_eval = sub.add_parser(
        "eval", help="Tier-1 retrieval eval + the nDCG regression gate"
    )
    p_eval.add_argument("-k", type=int, default=10)
    p_eval.add_argument(
        "--golden", help="path to a golden-set JSON (default: the frozen seed)"
    )
    p_eval.add_argument(
        "--update-baseline",
        action="store_true",
        help="ratchet the committed baseline to the current nDCG@10 (a reviewable diff)",
    )
    p_eval.set_defaults(func=_cmd_eval)

    p_eval_fit = sub.add_parser(
        "eval-fit",
        help="Tier-2 fit eval (nightly/pre-release; report-only unless --min-fit-precision)",
    )
    p_eval_fit.add_argument("-k", type=int, default=10)
    p_eval_fit.add_argument(
        "--golden", help="path to a golden-set JSON (default: the frozen seed)"
    )
    p_eval_fit.add_argument(
        "--sample", type=int, default=None, help="stratified sample cap (cost gate)"
    )
    p_eval_fit.add_argument(
        "--level", default="judge", choices=["listen", "judge"], help="fit-judge rung"
    )
    p_eval_fit.add_argument("--seed", type=int, default=0)
    p_eval_fit.add_argument(
        "--llm",
        default=None,
        choices=["fake", "local", "anthropic"],
        help="fit-judge provider (default: $FOLEY_LLM, else the deterministic fake)",
    )
    p_eval_fit.add_argument(
        "--min-fit-precision",
        type=float,
        default=None,
        dest="min_fit_precision",
        help="optional gate floor (nightly/pre-release only); omit for report-only",
    )
    p_eval_fit.add_argument(
        "--json", action="store_true", help="emit the full FitReport as JSON"
    )
    p_eval_fit.add_argument(
        "--baseline",
        action="store_true",
        help="gate against the committed fit baseline (same judge/rung/sample/seed only)",
    )
    p_eval_fit.add_argument(
        "--update-baseline",
        action="store_true",
        help="re-stamp the committed fit baseline from this run (a reviewable diff)",
    )
    p_eval_fit.set_defaults(func=_cmd_eval_fit)

    p_search = sub.add_parser("search", help="hybrid search of the default library")
    p_search.add_argument("query")
    p_search.add_argument("-k", type=int, default=10)
    p_search.add_argument(
        "--commercial-ok",
        action="store_true",
        help="keep only commercially-usable sounds (the default; kept for compatibility)",
    )
    p_search.add_argument(
        "--include-noncommercial",
        action="store_true",
        help="also return sounds that are not cleared for commercial use",
    )
    p_search.set_defaults(func=_cmd_search)

    p_kit = sub.add_parser(
        "agent-install",
        help="install the shipped agent kit (skill + /foley-score command + subagent) into .claude",
    )
    p_kit.add_argument(
        "--dest",
        default="./.claude",
        help="target agent-config dir (default ./.claude; use ~/.claude for all projects)",
    )
    p_kit.add_argument(
        "--overwrite", action="store_true", help="replace existing files/dirs"
    )
    p_kit.set_defaults(func=_cmd_agent_install)

    return add_verbs(parser)


def _cmd_agent_install(args) -> int:
    from .agent_kit import install_agent_kit

    installed = install_agent_kit(dest=args.dest, overwrite=args.overwrite)
    if installed:
        print(f"installed foley's agent kit into {args.dest}:")
        for p in installed:
            print(f"  {p}")
    else:
        print(
            f"nothing installed (already present in {args.dest}); pass --overwrite to replace."
        )
    return 0


#: Map an optional dependency's import name to the ``foley[extra]`` that ships it.
_MODULE_TO_EXTRA = {
    "numpy": "audio",
    "soundfile": "audio",
    "soxr": "audio",
    "librosa": "audio",
    "mixing": "audio",
    "scipy": "audio",
    "torch": "clap",
    "transformers": "clap",
    "torchaudio": "caption",
    "lancedb": "index",
    "sqlite_vec": "index-sqlite",
    "panns_inference": "tag",
}


def _missing_dep_hint(exc: ImportError) -> str:
    """A check_requirements-style install hint for a missing optional dependency."""
    module = (getattr(exc, "name", "") or "").split(".")[0]
    extra = _MODULE_TO_EXTRA.get(module)
    if extra:
        return (
            f"foley needs the optional dependency {module!r} for this command. "
            f"Install it with:  pip install 'foley[{extra}]'  "
            "(the CLAP model downloads on first use)."
        )
    return (
        f"foley could not import {module or 'a required module'!r}. "
        "Install the relevant extra, e.g. pip install 'foley[audio,clap]'."
    )


def main(argv: "Optional[list[str]]" = None) -> int:
    """Entry point for the ``foley`` console script."""
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        if hasattr(args, "func"):  # a command written here
            return args.func(args)
        import cw

        return cw.run(parser, argv, completion=False)  # a verb (#62)
    except ImportError as exc:  # heavy optional dep not installed — guide, don't dump
        print(_missing_dep_hint(exc), file=sys.stderr)
        return 1


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())
